python3 -c "
import json
with open('/app/resources/treasury_bulletin_1942_07.json', 'r') as f:
    data = json.load(f)

# Print keys and some structure
def print_structure(d, indent=0, max_keys=20):
    if isinstance(d, dict):
        print(' ' * indent + '{')
        for i, (k, v) in enumerate(d.items()):
            if i < max_keys:
                print(' ' * (indent+2) + f'\"{k}\": ', end='')
                if isinstance(v, dict):
                    print('{...}')
                elif isinstance(v, list):
                    print(f'[{len(v)} items]')
                else:
                    print(repr(v)[:50])
            else:
                print(' ' * (indent+2) + f'... ({len(d) - max_keys} more keys)')
                break
        print(' ' * indent + '}')
    elif isinstance(d, list):
        print(f'[{len(d)} items]')

print_structure(data)
"

